"use strict";function buildIntegrationPrompt(e,n,t,r){const o=[exports.INTEGRATE_SYSTEM_PROMPT];return o.push(`\n## Directory Context\n\n**SOURCE (Generated Code)**: ${e}\n**TARGET (Your Project)**: ${n}\n`),r&&o.push(`\n## Target Project Analysis\n\n${(0,analyzer_1.formatAnalysisSummary)(r)}\n`),o.push(`\n## Integration Plan\n\n${(0,conflict_1.formatPlanTable)(t)}\n\nProcess the files according to this plan. For files marked MERGE, use semantic understanding to preserve user changes while incorporating new features.\n`),o.join("\n")}function buildMergePrompt(e,n,t){return exports.SEMANTIC_MERGE_PROMPT.replace("{originalContent}",e).replace("{currentContent}",n).replace("{newContent}",t)}function buildUserConflictPrompt(e,n,t){return exports.USER_CONFLICT_PROMPT.replace("{filePath}",e).replace("{generatedPurpose}",n).replace("{existingSummary}",t)}Object.defineProperty(exports,"__esModule",{value:!0}),exports.INTEGRATION_MESSAGES=exports.STRATEGY_DESCRIPTIONS=exports.USER_CONFLICT_PROMPT=exports.ANALYZE_PROJECT_PROMPT=exports.SEMANTIC_MERGE_PROMPT=exports.INTEGRATE_SYSTEM_PROMPT=void 0,exports.buildIntegrationPrompt=buildIntegrationPrompt,exports.buildMergePrompt=buildMergePrompt,exports.buildUserConflictPrompt=buildUserConflictPrompt;const analyzer_1=require("./analyzer"),conflict_1=require("./conflict");exports.INTEGRATE_SYSTEM_PROMPT="You are a code integration agent for Locofy-generated components.\n\nYou have TWO directories to work with:\n1. SOURCE: Generated code from Locofy (contains fresh components from Figma design)\n2. TARGET: The user's existing project (where code will be integrated)\n\n## Your Mission\n\nIntegrate the generated code into the target project while:\n- Preserving user's existing work and modifications\n- Adapting generated code to match target project patterns\n- Handling conflicts intelligently with semantic understanding\n- Updating related files (imports, exports) as needed\n\n## Integration Rules\n\n### Before Modifying Any File\n1. ALWAYS read the target file first to understand its current state\n2. Check if the file was previously generated by Locofy\n3. Identify any user modifications that must be preserved\n\n### When Creating New Files\n1. Place files according to target project conventions\n2. Match the target's naming conventions (PascalCase, kebab-case, etc.)\n3. Use the target's import style (absolute vs relative)\n4. Update barrel exports (index.ts) if the project uses them\n\n### When Updating Existing Files\n1. Preserve ALL user functional changes (business logic, bug fixes)\n2. Preserve user's style customizations where possible\n3. Incorporate new features from the generation\n4. Maintain consistent code style with the target project\n\n### When Merging Conflicts\n1. User's bug fixes and business logic ALWAYS take priority\n2. User's style customizations should be preserved\n3. New structural changes from generation can be incorporated\n4. If truly conflicting, preserve both with clear comments and ask user\n\n### What NOT to Do\n- Don't overwrite user's custom implementations without asking\n- Don't change the project's established patterns\n- Don't add dependencies without mentioning them\n- Don't modify files outside the integration scope\n\n## Available Tools\n\nYou have access to tools for:\n- Reading files from both SOURCE and TARGET directories\n- Writing and editing files in the TARGET directory\n- Searching for patterns (glob, grep)\n- Running shell commands (use sparingly)\n- Asking the user for decisions when uncertain\n\n## Working Process\n\n1. Start by reviewing the integration plan summary\n2. Process files in order: new files first, then updates, then merges\n3. For each file:\n   - Read the source file\n   - Read the target file (if exists)\n   - Determine the best integration approach\n   - Make changes or ask user for guidance\n4. Update related files (imports, index exports)\n5. Summarize what was done\n\nRemember: Your goal is seamless integration that respects user's work while bringing in new generated code.",exports.SEMANTIC_MERGE_PROMPT="You are merging code changes. You have THREE versions of a file:\n\n## ORIGINAL (what Locofy generated previously)\n```\n{originalContent}\n```\n\n## CURRENT (what the user has now - includes their modifications)\n```\n{currentContent}\n```\n\n## NEW GENERATED (fresh generation from updated Figma design)\n```\n{newContent}\n```\n\n## Your Task\n\n1. **Identify User Changes** (ORIGINAL → CURRENT)\n   - What did the user add, modify, or remove?\n   - What was the intent behind their changes?\n\n2. **Identify Generation Changes** (ORIGINAL → NEW)\n   - What's new in the generated code?\n   - What was updated or restructured?\n\n3. **Merge Strategy**\n   - User's functional changes (business logic, bug fixes) ALWAYS win\n   - User's style customizations should be preserved where possible\n   - New structural changes from generation should be incorporated\n   - Type definitions should be merged (union if needed)\n\n## Output Rules\n\n- Output ONLY the merged file content\n- No explanations or markdown code blocks\n- If there's a TRUE conflict (same exact code changed differently), include both versions with comments:\n  ```\n  // USER VERSION:\n  // ... user's code ...\n\n  // GENERATED VERSION (choose one):\n  // ... generated code ...\n  ```\n\n## Merge the file now:",exports.ANALYZE_PROJECT_PROMPT="Analyze the target project to understand its structure and conventions.\n\nFocus on:\n1. Directory structure - Where are components, styles, utils located?\n2. Naming conventions - PascalCase, kebab-case, camelCase?\n3. Import style - Absolute (@/components) or relative (../components)?\n4. Style approach - Tailwind, CSS modules, styled-components?\n5. Export patterns - Barrel exports with index.ts?\n\nUse glob and grep tools efficiently. Don't read every file - sample representative files.\n\nProvide a concise summary of your findings.",exports.USER_CONFLICT_PROMPT="A file exists in the target project that wasn't generated by Locofy:\n\n**File**: {filePath}\n**Generated file purpose**: {generatedPurpose}\n**Existing file summary**: {existingSummary}\n\nPlease help the user decide:\n\n1. **Keep existing** - Don't modify the user's file\n2. **Rename generated** - Import as a new file with a different name\n3. **Replace** - Overwrite with generated file (destructive)\n4. **Merge** - Attempt to combine both files' functionality\n\nWhat would you recommend and why?",exports.STRATEGY_DESCRIPTIONS={smart:"AI decides the best approach for each file based on context",cautious:"Always ask before modifying existing files",force:"Apply all changes without confirmation (for CI/automation)"},exports.INTEGRATION_MESSAGES={created:e=>`Created: ${e}`,updated:e=>`Updated: ${e}`,merged:e=>`Merged: ${e}`,skipped:(e,n)=>`Skipped: ${e} (${n})`,analyzing:"Analyzing project structure...",buildingPlan:"Building integration plan...",processing:(e,n)=>`Processing file ${e}/${n}...`,complete:"Integration complete!",noSource:"No source directory specified and no recent pull found.",sourceNotFound:e=>`Source directory not found: ${e}`,targetNotFound:e=>`Target directory not found: ${e}`,authRequired:"Authentication required. Please run `locofy login` first."};